mapper.select:
/* StatTaskMapper.selectListTotCnt */
SELECT COUNT(*) FROM( SELECT * FROM ( SELECT NVL(CATE,'총합계') AS CATE , INPT_ATMC_BIZ_DSCD , INPT_RCP_DT , AUTH , AI_INPT_AUT_CD , USER_ID , AI_INPT_USER_NM , CASE WHEN INPT_ATMC_BIZ_DSCD IS NOT NULL THEN SUM(COUNT_ENO) OVER (PARTITION BY CATE, INPT_RCP_DT, USER_ID) ELSE SUM(COUNT_ENO) END COUNT_ENO , CASE WHEN INPT_ATMC_BIZ_DSCD IS NOT NULL THEN SUBSTR('0000'||FLOOR(FLOOR(ROUND(NVL(SUM(TOTAL_TIME) OVER(PARTITION BY CATE, INPT_RCP_DT, USER_ID),0)) / 60) / 60),-4,4)||':' ||SUBSTR('0'||MOD(FLOOR(ROUND(NVL(SUM(TOTAL_TIME) OVER(PARTITION BY CATE, INPT_RCP_DT, USER_ID),0)) / 60),60),-2,2)||':' ||SUBSTR('0'||MOD(ROUND(NVL(SUM(TOTAL_TIME) OVER(PARTITION BY CATE, INPT_RCP_DT, USER_ID),0)),60),-2,2) ELSE SUBSTR('0000'||FLOOR(FLOOR(ROUND(NVL(SUM(TOTAL_TIME),0)) / 60) / 60),-4,4)||':' ||SUBSTR('0'||MOD(FLOOR(ROUND(NVL(SUM(TOTAL_TIME),0)) / 60),60),-2,2)||':' ||SUBSTR('0'||MOD(ROUND(NVL(SUM(TOTAL_TIME),0)),60),-2,2) END TOTAL_TIME
, CASE WHEN INPT_ATMC_BIZ_DSCD IS NOT NULL THEN SUBSTR('0000'||FLOOR(FLOOR(ROUND(NVL((SUM(TOTAL_TIME) OVER(PARTITION BY CATE, INPT_RCP_DT, USER_ID) / SUM(COUNT_ENO) OVER (PARTITION BY CATE, INPT_RCP_DT, USER_ID)),0)) / 60) / 60),-4,4)||':' ||SUBSTR('0'||MOD(FLOOR(ROUND(NVL((SUM(TOTAL_TIME) OVER(PARTITION BY CATE, INPT_RCP_DT, USER_ID) / SUM(COUNT_ENO) OVER (PARTITION BY CATE, INPT_RCP_DT, USER_ID)),0)) / 60),60),-2,2)||':' ||SUBSTR('0'||MOD(ROUND(NVL((SUM(TOTAL_TIME) OVER(PARTITION BY CATE, INPT_RCP_DT, USER_ID) / SUM(COUNT_ENO) OVER (PARTITION BY CATE, INPT_RCP_DT, USER_ID)),0)),60),-2,2) ELSE NULL END AVG_TIME , SUM(TOTAL_TIME) OVER(PARTITION BY CATE, INPT_RCP_DT, USER_ID) / SUM(COUNT_ENO) OVER (PARTITION BY CATE, INPT_RCP_DT, USER_ID) AS AVGE FROM LIST GROUP BY GROUPING SETS ((CATE, INPT_ATMC_BIZ_DSCD, INPT_RCP_DT, AUTH, AI_INPT_AUT_CD, USER_ID, AI_INPT_USER_NM, COUNT_ENO, TOTAL_TIME, AVG_TIME, AVGE, INPT_MST_SRNO),()) )MASTER GROUP BY CATE, INPT_RCP_DT, USER_ID ,INPT_ATMC_BIZ_DSCD, AUTH, AI_INPT_AUT_CD, AI_INPT_USER_NM, COUNT_ENO, TOTAL_TIME, AVG_TIME, AVGE
)
